import pytest

from minisheet.refs import Ref, parse_range, parse_ref, to_a1


# B§1 table rows
def test_parse_ref_b12():
    assert parse_ref("B12") == Ref(1, 11, False, False)


def test_parse_ref_absolute_zz9999():
    assert parse_ref("$zz$9999") == Ref(701, 9998, True, True)


def test_parse_range_mixed_absolute_normalized():
    assert parse_range("$C3:A$1") == (
        Ref(0, 0, False, True),
        Ref(2, 2, True, False),
    )


def test_to_a1_absolute_col_aa():
    assert to_a1(Ref(26, 0, True, False)) == "$AA1"


def test_parse_ref_a0_rejected():
    with pytest.raises(ValueError):
        parse_ref("A0")


def test_parse_ref_aaa1_rejected():
    with pytest.raises(ValueError):
        parse_ref("AAA1")


# Review Focus
def test_a01_rejected():
    with pytest.raises(ValueError):
        parse_ref("A01")


def test_range_bare_cell():
    with pytest.raises(ValueError):
        parse_range("A1")


def test_to_a1_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(702, 0))


# Additional spec coverage
def test_parse_ref_a10000_rejected():
    with pytest.raises(ValueError):
        parse_ref("A10000")


def test_parse_ref_zz9999_max_ok():
    assert parse_ref("ZZ9999") == Ref(701, 9998, False, False)


def test_parse_ref_a1_origin():
    assert parse_ref("A1") == Ref(0, 0, False, False)


def test_parse_ref_lowercase_accepted():
    assert parse_ref("b12") == Ref(1, 11, False, False)


def test_parse_ref_absolute_col_only():
    assert parse_ref("$B12") == Ref(1, 11, True, False)


def test_parse_ref_absolute_row_only():
    assert parse_ref("B$12") == Ref(1, 11, False, True)


@pytest.mark.parametrize("bad", ["", "1", "A", "A-1", "A1 ", " A1", "A1B", "$$A1", "A$$1", "AAA$1"])
def test_parse_ref_malformed_rejected(bad):
    with pytest.raises(ValueError):
        parse_ref(bad)


def test_parse_range_a1_a1_valid():
    assert parse_range("A1:A1") == (Ref(0, 0), Ref(0, 0))


def test_parse_range_normalizes_reversed_corners():
    assert parse_range("C3:A1") == (Ref(0, 0), Ref(2, 2))


def test_parse_range_tie_takes_first_corner_flags():
    # both corners share column A; first corner supplies the column flag
    assert parse_range("$A1:A$1") == (Ref(0, 0, True, False), Ref(0, 0, False, True))


def test_parse_range_malformed_rejected():
    with pytest.raises(ValueError):
        parse_range("A1:")


def test_parse_range_bad_corner_rejected():
    with pytest.raises(ValueError):
        parse_range("A0:B2")


def test_to_a1_origin():
    assert to_a1(Ref(0, 0)) == "A1"


def test_to_a1_max():
    assert to_a1(Ref(701, 9998)) == "ZZ9999"


def test_to_a1_absolute_row_only():
    assert to_a1(Ref(1, 11, False, True)) == "B$12"


def test_to_a1_row_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(0, 9999))


def test_to_a1_negative_col_rejected():
    with pytest.raises(ValueError):
        to_a1(Ref(-1, 0))

